\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 A modern, feature-rich project dashboard for REAPER built with ReaImGui. Browse, search, filter, and manage your projects with metadata, tags, and album art.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Requirements:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab ReaImGui\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab SWS Extensions\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Automatically aligns two audio items by their audio content using MFCC cross-correlation. Best for aligning ~95%-100% similar recordings of the same source (vocals + instrumental, stem tracks, etc).\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Workflow:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Select exactly 2 audio items\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Run this script\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Review detected offset and confidence score\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab Optionally apply Phase Alignment (native REAPER micro-alignment)\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Reference/Target Assignment:} Lower track number = reference (stays put). Same track: earlier position = reference.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Requirements:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Python 3.x (https://www.python.org)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab pip install audio-offset-finder\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab FFmpeg in PATH (https://ffmpeg.org)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Companion file: align_helper.py (same folder as script)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Floating control panel for quick access to custom scripts and tools. Features a single "Default" section with hardcoded scripts + auto-discovered scripts, a live project info strip, and fully customizable button layout via cc_buttons.json.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b How it works:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Hardcoded buttons: 9 core scripts (Extract Tempo Map, Import Moises Stems, etc.)\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab ReaDashboard from the sibling ReaDashboard/ folder\sa180\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Auto-detected buttons: Any new .lua/.eel scripts in the Scripts folder are automatically discovered and added with tooltips from @description headers\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Custom layout: Users can customize via the built-in editor \u8594 ? saves to cc_buttons.json\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Requirements:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab ReaImGui extension (install via Extensions > ReaPack)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Companion file: json.lua (same folder as script)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Optional: cc_buttons.json for button customization\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Deletes all tempo/time signature markers from the project after confirmation.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Run the script and confirm the deletion prompt. Supports undo with Ctrl+Z.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Exports all tempo and time signature markers from the current project to a CSV file.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 The user chooses the output path via file dialog. Requires the project to be saved.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Requirements:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab js_ReaScriptAPI extension (install via Extensions > ReaPack)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Extracts a tempo map from a perfectly-aligned click track using transient detection and grid analysis. Useful for recordings that need accurate tempo mapping without relying on beat detection AI.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Workflow:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Select an audio item containing a click track or metronome\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Run this script\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Configure anchor point, time signature, and transient detection settings\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab Place markers at detected transients and snap to nearest grid\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 5.\tx360\tab Review and approve; markers are converted to the project tempo envelope\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Requirements:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab SWS Extensions (for SNM transient detection functions)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Python 3.x (for optional tempo normalization)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab beat_this or beat_net packages (optional, for advanced detection)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Detects beats and downbeats in an audio item using the Beat This! machine learning model, then converts them into a project tempo map with automatic anchor/setup tempos.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Workflow:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Select a drum stem or metronome audio item\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Run this script (or select 2+ items to mix for richer detection)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Configure source type (auto/click/drum/mix), BPM hint, detail level\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab Phase 1: place markers at detected beats and snap to transients\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 5.\tx360\tab Phase 2: review and convert markers to tempo envelope\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Requirements:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Python 3.x (https://www.python.org)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab pip install torch (from https://pytorch.org \u8212- match your CUDA version)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab pip install tqdm einops soxr rotary-embedding-torch soundfile\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab pip install https://github.com/CPJKU/beat_this/archive/main.zip\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab FFmpeg in PATH (https://ffmpeg.org)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab SWS Extensions (for advanced snap features)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Companion files: beat_this_helper.py, audio_mix_helper.py (same folder as script)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Imports all audio stems from a Moises archive or extracted folder into a structured folder track in REAPER.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Workflow:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Run this script\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Pick EITHER:\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab A Moises archive (.zip, .7z, etc.) \u8212- will extract first\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab Any audio stem file (.wav/.mp3/.m4a/.flac) in an already-extracted folder \u8212- will scan and import\sa180\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab All stems are imported as child tracks with pre-set volumes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab Unrecognized audio files are added in a "Pass 2" sweep (future-proofs for new stems)\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Supported Formats:} WAV, MP3, M4A, FLAC\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Supported Archives:} ZIP, 7Z, RAR, tar.gz, tgz, tar.bz2, tar.xz\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Requirements:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab js_ReaScriptAPI extension (install via Extensions > ReaPack)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Windows 10/11 (uses built-in tar/bsdtar for archive extraction)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Note: RAR archives are NOT supported by Windows built-in tar; use ZIP/7Z instead\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Imports tempo and time signature markers into the current project from a CSV file.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 The user chooses the CSV file via file dialog. The imported markers must match the CSV format produced by "Export Tempo Map to CSV" (v2.2+).\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Requirements:}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab js_ReaScriptAPI extension (install via Extensions > ReaPack)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Anshul's REAPER Scripts\par}
{\pard \ql \f0 \sa180 \li0 \fi0 A collection of personal scripts for REAPER \u8212- built for my workflow as a guitarist learning and covering songs.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 What's Included\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b ReaDashboard} \u8212- Modern project launcher built with ReaImGui. Browse, search, filter, and manage your REAPER projects with album art, custom tags, metadata, grid/list views, and keyboard navigation.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Command Center GUI} \u8212- Floating toolbar for quick access to all scripts (9 core scripts + auto-discovered scripts). Includes ReaDashboard, tempo mapping, audio alignment, and stem import tools. Fully customizable and extensible.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Workflow Scripts} \u8212- Tempo mapping (AI-powered beat detection from audio or click tracks), audio alignment via MFCC cross-correlation, tempo map import/export, video/audio stretching to match tempo, and Moises stem import with automatic track organization.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Quick Start\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab In REAPER: {\f1 Extensions > ReaPack > Import repositories}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Paste: {\f1 https://raw.githubusercontent.com/AnshulJ999/REAPER-ReaScripts/main/index.xml}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Browse and install what you need\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Or download manually and place scripts in your REAPER Scripts folder.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 For full documentation, see the README files in the GitHub repository https://github.com/AnshulJ999/REAPER-ReaScripts.\par}
}
